{"code":"import pandas as pd, statsmodels.formula.api as smf
x=pd.read_csv('data/explore.csv')
cols=['nitrogen_ppm','phosphorus_ppm','potassium_ppm','soil_ph','irrigation_mm','seed_density','mulch_depth_cm','biochar_g','fungicide_ml','shade_pct']
for c in cols:
 m=smf.ols(f'yield_kg ~ {c} + C(farm)',x).fit()
 print(c, round(m.params[c],4), round(m.pvalues[c],6), round(m.rsquared,4))"}
